import heapq
from collections import defaultdict

def min_days_to_pass_exams(n, m, daily_exams, preparation_times):
    # Create a list of available preparation days for each subject
    prep_days = [defaultdict(int) for _ in range(m + 1)]

    # Populate the preparation days list
    for day, subject in enumerate(daily_exams, start=1):
        if subject != 0:
            prep_days[subject][day] += 1

    # Priority queue to store exams with their latest preparation day
    pq = []
    last_day = {}

    for day in range(1, n + 1):
        # Add new preparation days to the priority queue
        for subject, count in prep_days.items():
            if day in count:
                heapq.heappush(pq, (-count[day], subject))

        # Check if there's an exam to take today
        if pq:
            _, subject = heapq.heappop(pq)
            if subject not in last_day or day > last_day[subject]:
                last_day[subject] = day
                preparation_times[subject] -= 1

        # Remove completed preparations from the priority queue
        while pq and preparation_times[pq[0][1]] == 0:
            heapq.heappop(pq)

    # Check if all exams can be passed
    if any(preparation_times[i] > 0 for i in range(1, m + 1)):
        return -1

    # Return the maximum day used
    return max(last_day.values())

