from collections import defaultdict, deque

def min_days_to_pass_exams(n, m, daily_exams, preparation_times):
    last_day = {i: -1 for i in range(1, m + 1)}
    available_preparation_days = defaultdict(deque)

    for i in range(m):
        available_preparation_days[i+1].append(i+1)

    total_days = 0

    for day in range(n):
        if daily_exams[day] != 0:
            exam = daily_exams[day]
            if last_day[exam] == -1:
                if available_preparation_days[exam]:
                    last_day[exam] = available_preparation_days[exam][0]
                    available_preparation_days[exam].popleft()
                else:
                    return -1
            total_days = max(total_days, last_day[exam])
        elif available_preparation_days:
            exam = available_preparation_days[min(available_preparation_days.keys())][0]
            if last_day[exam] == -1:
                last_day[exam] = total_days + 1
                available_preparation_days[exam].popleft()
            total_days = max(total_days, last_day[exam])

    return total_days + 1

